export default function BalanceIndicator({ average }) {
  const display = useMemo(() => {
    if (average == null || isNaN(average)) return '--'
    return Number(average).toFixed(1)
  }, [average])

  // SVG arc: semicircle from 180 to 0 degrees
  // The arc fills proportionally based on the average (1-10 mapped to 0-100%)
  const percentage = average != null ? ((average - 1) / 9) * 100 : 0
  const radius = 70
  const circumference = Math.PI * radius // semicircle
  const filled = (percentage / 100) * circumference

  // Determine color based on score
  const getColor = () => {
    if (average == null) return '#d1d5db'
    if (average >= 7) return '#629978'   // calm-500
    if (average >= 4) return '#d6854b'   // warmth-500
    return '#c87040'                      // warmth-600
  }

  return (
    <div className="flex flex-col items-center py-4">
      <div className="relative w-48 h-28">
        <svg
          viewBox="0 0 160 90"
          className="w-full h-full"
          aria-hidden="true"
        >
          {/* Background arc */}
          <path
            d="M 10 80 A 70 70 0 0 1 150 80"
            fill="none"
            stroke="#e5e7eb"
            strokeWidth="8"
            strokeLinecap="round"
          />
          {/* Filled arc */}
          <path
            d="M 10 80 A 70 70 0 0 1 150 80"
            fill="none"
            stroke={getColor()}
            strokeWidth="8"
            strokeLinecap="round"
            strokeDasharray={`${filled} ${circumference}`}
            className="transition-all duration-700"
          />
        </svg>

        {/* Centered number */}
        <div className="absolute inset-0 flex flex-col items-center justify-end pb-1">
          <span
            className="text-4xl font-semibold tabular-nums"
            style={{ color: getColor() }}
          >
            {display}
          </span>
        </div>
      </div>

      <p className="text-sm text-gray-500 mt-1">Overall Balance</p>
    </div>
  )
}
"}

