const categoryColors = {
  physical: { dot: 'bg-calm-500', label: 'Physical' },
  mental: { dot: 'bg-sky-500', label: 'Mental' },
  emotional: { dot: 'bg-warmth-500', label: 'Emotional' },
  identity: { dot: 'bg-soul-500', label: 'Identity' },
}

const categoryKeys = ['physical', 'mental', 'emotional', 'identity']

function formatDate(dateStr) {
  const date = new Date(dateStr)
  const now = new Date()
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const target = new Date(date.getFullYear(), date.getMonth(), date.getDate())
  const diffDays = Math.round((today - target) / (1000 * 60 * 60 * 24))

  if (diffDays === 0) return 'Today'
  if (diffDays === 1) return 'Yesterday'
  if (diffDays < 7) {
    return date.toLocaleDateString('en-US', { weekday: 'long' })
  }
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined,
  })
}

function getLowestCategory(checkin) {
  let lowest = null
  let lowestScore = Infinity
  for (const key of categoryKeys) {
    const score = checkin[`${key}Score`]
    if (score != null && score < lowestScore) {
      lowestScore = score
      lowest = key
    }
  }
  return lowest
}

function getPreviewNote(checkin) {
  const noteFields = [
    'dominoEffect',
    'feltMostLikeMyself',
    'feltLeastLikeMyself',
    'needTomorrow',
    'partnerShouldUnderstand',
    'physicalHelped', 'physicalDrained',
    'mentalHelped', 'mentalDrained',
    'emotionalHelped', 'emotionalDrained',
    'identityHelped', 'identityDrained',
  ]
  for (const field of noteFields) {
    const val = checkin[field]
    if (val && val.trim()) {
      const text = val.trim()
      return text.length > 80 ? text.slice(0, 77) + '...' : text
    }
  }
  return null
}

export default function HistoryEntry({ checkin, onView, onDelete }) {
  const [confirming, setConfirming] = useState(false)

  const scores = categoryKeys.map((key) => ({
    key,
    score: checkin[`${key}Score`],
    ...categoryColors[key],
  }))

  const average =
    scores.reduce((sum, s) => sum + (s.score || 0), 0) / scores.length

  const lowest = getLowestCategory(checkin)
  const preview = getPreviewNote(checkin)

  const handleDelete = () => {
    if (confirming) {
      onDelete(checkin.id)
      setConfirming(false)
    } else {
      setConfirming(true)
    }
  }

  return (
    <div
      className="bg-white rounded-xl p-4 shadow-sm hover:shadow-md transition-shadow cursor-pointer"
      onClick={() => onView(checkin)}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          onView(checkin)
        }
      }}
    >
      <div className="flex items-start justify-between mb-3">
        <div>
          <p className="text-sm font-medium text-gray-700">
            {formatDate(checkin.date || checkin.createdAt)}
          </p>
          {lowest && (
            <p className="text-xs text-gray-400 mt-0.5">
              Lowest: {categoryColors[lowest].label}
            </p>
          )}
        </div>

        <span className="text-lg font-semibold text-gray-600 tabular-nums">
          {average.toFixed(1)}
        </span>
      </div>

      {/* Score badges */}
      <div className="flex gap-2 mb-3">
        {scores.map(({ key, score, dot, label }) => (
          <div
            key={key}
            className="flex items-center gap-1.5 text-xs text-gray-500"
            title={label}
          >
            <span className={`w-2.5 h-2.5 rounded-full ${dot}`} />
            <span className="tabular-nums">{score}</span>
          </div>
        ))}
      </div>

      {/* Notes preview */}
      {preview && (
        <p className="text-xs text-gray-400 line-clamp-1 mb-3">
          {preview}
        </p>
      )}

      {/* Actions */}
      <div
        className="flex justify-end gap-2"
        onClick={(e) => e.stopPropagation()}
      >
        <button
          onClick={handleDelete}
          onBlur={() => setConfirming(false)}
          className={`text-xs px-3 py-1.5 rounded-lg transition-colors ${
            confirming
              ? 'bg-red-50 text-red-600 hover:bg-red-100'
              : 'text-gray-400 hover:text-red-500 hover:bg-red-50'
          }`}
        >
          {confirming ? 'Confirm delete?' : 'Delete'}
        </button>
      </div>
    </div>
  )
}
"}

