const periodLabels = {
  '7d': '7 days',
  '14d': '14 days',
  '30d': '30 days',
  '90d': '90 days',
}

function buildMessage(trends) {
  if (!trends || trends.totalEntries < 2) {
    return 'Keep logging your energy to see patterns emerge.'
  }

  const parts = []
  const periodLabel = periodLabels[trends.period] || trends.period || '7 days'

  // Overall averages message
  if (trends.averages) {
    const entries = Object.entries(trends.averages)
      .filter(([key]) => categoryNames[key])
      .sort((a, b) => a[1] - b[1])

    if (entries.length > 0) {
      const [lowestKey, lowestVal] = entries[0]
      const [highestKey, highestVal] = entries[entries.length - 1]

      parts.push(
        `Over the last ${periodLabel}, your ${categoryNames[highestKey]} energy averaged ${Number(highestVal).toFixed(1)}, ` +
        `while ${categoryNames[lowestKey]} sat at ${Number(lowestVal).toFixed(1)}.`
      )
    }
  }

  // Lowest most often
  if (trends.lowestMostOften && categoryNames[trends.lowestMostOften]) {
    parts.push(
      `${categoryNames[trends.lowestMostOften]} has been your lowest category most often.`
    )
  }

  // Entry count
  if (trends.totalEntries) {
    parts.push(
      `Based on ${trends.totalEntries} check-in${trends.totalEntries === 1 ? '' : 's'}.`
    )
  }

  return parts.join(' ')
}

