  ]
  lines.push(scores.map(([name, val]) => `${name}: ${val}/10`).join('  |  '))

  // Notes
  const noteFields = [
    ['physicalHelped', 'Physical (helped)'],
    ['physicalDrained', 'Physical (drained)'],
    ['mentalHelped', 'Mental (helped)'],
    ['mentalDrained', 'Mental (drained)'],
    ['emotionalHelped', 'Emotional (helped)'],
    ['emotionalDrained', 'Emotional (drained)'],
    ['identityHelped', 'Identity (helped)'],
    ['identityDrained', 'Identity (drained)'],
    ['dominoEffect', 'Domino effect'],
    ['feltMostLikeMyself', 'Most like myself'],
    ['feltLeastLikeMyself', 'Least like myself'],
    ['needTomorrow', 'Need tomorrow'],
    ['partnerShouldUnderstand', 'Partner should understand'],
  ]

  for (const [field, label] of noteFields) {
    if (checkin[field]?.trim()) {
      lines.push(`${label}: ${checkin[field].trim()}`)
    }
  }

  return lines.join('\n')
}

export default function ExportPanel() {
  const [from, setFrom] = useState('')
  const [to, setTo] = useState('')
  const [copied, setCopied] = useState(false)
  const [copying, setCopying] = useState(false)

  const handleExportCSV = () => {
    exportCSV(from || undefined, to || undefined)
  }

  const handleCopySummary = async () => {
    setCopying(true)
    try {
      const checkins = await getCheckIns(from || undefined, to || undefined)
      const list = Array.isArray(checkins) ? checkins : checkins?.data || []

      if (!list.length) {
        await navigator.clipboard.writeText('No check-ins found for the selected period.')
      } else {
        const text = list.map(formatCheckInAsText).join('\n\n')
        await navigator.clipboard.writeText(text)
      }

      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch (err) {
      console.error('Failed to copy summary:', err)
    } finally {
      setCopying(false)
    }
  }

  return (
    <div className="rounded-xl bg-white p-5 shadow-sm space-y-5">
      <h3 className="text-sm font-medium text-gray-600">Export Data</h3>

      {/* Date range */}
      <div className="grid gap-3 sm:grid-cols-2">
        <div>
          <label className="block text-xs text-gray-400 mb-1">From</label>
          <input
            type="date"
            value={from}
            onChange={(e) => setFrom(e.target.value)}
            className="w-full rounded-lg border border-gray-200 px-3 py-2 text-sm text-gray-700
              focus:outline-none focus:ring-2 focus:ring-calm-300 focus:border-transparent"
          />
        </div>
        <div>
          <label className="block text-xs text-gray-400 mb-1">To</label>
          <input
            type="date"
            value={to}
            onChange={(e) => setTo(e.target.value)}
            className="w-full rounded-lg border border-gray-200 px-3 py-2 text-sm text-gray-700
              focus:outline-none focus:ring-2 focus:ring-calm-300 focus:border-transparent"
          />
        </div>
      </div>

      {/* Action buttons */}
      <div className="flex gap-3">
        <button
          onClick={handleExportCSV}
          className="flex-1 py-2.5 rounded-xl bg-calm-500 text-white text-sm font-medium
            hover:bg-calm-600 active:bg-calm-700 transition-colors shadow-sm"
        >
          Download CSV
        </button>

        <button
          onClick={handleCopySummary}
          disabled={copying}
          className="flex-1 py-2.5 rounded-xl border border-gray-200 text-sm font-medium
            text-gray-600 hover:bg-gray-50 active:bg-gray-100
            disabled:opacity-50 disabled:cursor-not-allowed
            transition-colors"
        >
          {copied ? 'Copied!' : copying ? 'Copying...' : 'Copy Summary'}
        </button>
      </div>
    </div>
  )
}
"}

